import{_ as e,o as n,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Report 2 — Checklist sửa theo BA V2 + Feature","description":"","frontmatter":{},"headers":[],"relativePath":"plan/report2-fix-checklist.md","filePath":"plan/report2-fix-checklist.md"}'),a={name:"plan/report2-fix-checklist.md"};function r(h,t,d,c,s,l){return n(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="report-2-—-checklist-sua-theo-ba-v2-feature" tabindex="-1">Report 2 — Checklist sửa theo BA V2 + Feature <a class="header-anchor" href="#report-2-—-checklist-sua-theo-ba-v2-feature" aria-label="Permalink to &quot;Report 2 — Checklist sửa theo BA V2 + Feature&quot;">​</a></h1><p>&gt; Mục đích: đối chiếu <code>FormReportDA/reports/BrandHub_Report2_Project_Management_Plan.docx</code> với nghiệp vụ mới trong <code>docs/ba/</code> (V2, 2026-09-14) và <code>docs/feature/</code>, liệt kê từng điểm cần sửa + cách sửa cụ thể. &gt; &gt; Nguồn sự thật: <code>docs/ba/00-overview.md</code> (109 FR, 105 UC, 9 domain, deadline 19/12/2026), <code>docs/feature/</code> (124 folder), <code>docs/plan/sprint-plan-v2-overview.md</code>, <code>docs/plan/brandhub-master-plan.md</code>.</p><hr><h2 id="tong-quan-van-đe" tabindex="-1">Tổng quan vấn đề <a class="header-anchor" href="#tong-quan-van-đe" aria-label="Permalink to &quot;Tổng quan vấn đề&quot;">​</a></h2><p>Report 2 đang là <strong>skeleton theo mô hình CŨ</strong>: 1-tầng Workspace, RBAC 6 role cố định, 16 sprint, ~46 epic, ~406 task, deadline tháng 11/2026. BA V2 đã thay đổi nền tảng nghiệp vụ, nên toàn bộ phần <strong>Scope &amp; Estimation</strong> và <strong>mô hình org/RBAC</strong> lệch nặng, còn lại là chỉnh số liệu lẻ.</p><p>Thứ tự ưu tiên sửa: <strong>(1) Scope/WBS → (2) mô hình org → (3) risk → (4) training/tech → (5) responsibility → (6) linh tinh.</strong></p><hr><h2 id="_1-scope-estimation-§1-1-—-so-lieu-cu-toan-bo" tabindex="-1">1. Scope &amp; Estimation (§1.1) — số liệu cũ toàn bộ <a class="header-anchor" href="#_1-scope-estimation-§1-1-—-so-lieu-cu-toan-bo" aria-label="Permalink to &quot;1. Scope &amp; Estimation (§1.1) — số liệu cũ toàn bộ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Hiện tại (Report 2)</th><th>Sửa thành</th><th>Cách sửa</th></tr></thead><tbody><tr><td>Số sprint</td><td>16 sprints + 4 AI iterations</td><td>Re-scope. Sprint plan V2 chỉ chốt Sprint 8–12 (5 sprint / 10 tuần); Sprint 13–14 Trung tự lo</td><td>Cập nhật theo <code>sprint-plan-v2-overview.md</code>, bỏ khái niệm &quot;16 sprint cứng&quot;</td></tr><tr><td>Số epic/task</td><td>~46 epics, ~406 tasks</td><td>109 FR / 105 Use Case / 9 domain</td><td>Dựng lại WBS từ danh sách FR (<code>Các FR của hệ thống - Feature_Function Requirement.csv</code>)</td></tr><tr><td>Man-day</td><td>860–900 man-days (5 người x 32 tuần)</td><td>Tính lại theo 109 FR + deadline mới 19/12/2026</td><td>Re-estimate mỗi FR theo độ phức tạp (S/M/C)</td></tr><tr><td>Deadline</td><td>Tháng 11/2026 (ngầm định)</td><td><strong>19/12/2026</strong></td><td>Ghi rõ trong §1.1, trích <code>ba/00-overview.md</code></td></tr></tbody></table><p><strong>Thêm 9 domain mới vào WBS</strong> (Report 2 chưa nêu):</p><ol><li>Media Package → Media Campaign (FR 3.5.1–3.5.10)</li><li>Task &amp; Content Workflow (FR 3.6.1–3.6.35)</li><li>Publishing &amp; Social (FR 3.8.1–3.8.16)</li><li>Subscription &amp; Billing (FR 3.9.1–3.9.7)</li><li>Admin (FR 3.10.1–3.10.12)</li><li>AI Features (FR 3.7.1–3.7.12)</li><li>Authentication (FR 3.2.1–3.2.9)</li><li>Profile (FR 3.3.1–3.3.4)</li><li>Agency/Workspace (FR 3.4.1–3.4.21)</li></ol><p>&gt; ⚠️ <strong>Chốt số FR trước khi dựng WBS.</strong> BA ghi 109 FR, nhưng <code>docs/feature/</code> có 124 folder (thiếu <code>3-10-10</code>, vài FR chia nhỏ). Đếm lại FR chuẩn từ CSV, thống nhất 1 con số.</p><hr><h2 id="_2-mo-hinh-nghiep-vu-—-report-2-khong-đe-cap-them-moi" tabindex="-1">2. Mô hình nghiệp vụ — Report 2 KHÔNG đề cập (thêm mới) <a class="header-anchor" href="#_2-mo-hinh-nghiep-vu-—-report-2-khong-đe-cap-them-moi" aria-label="Permalink to &quot;2. Mô hình nghiệp vụ — Report 2 KHÔNG đề cập (thêm mới)&quot;">​</a></h2><p>Các khái niệm sau <strong>bắt buộc</strong> phải xuất hiện trong §1.1 hoặc overview, nếu không report 2 lạc so với SRS (Report 3):</p><table tabindex="0"><thead><tr><th>Khái niệm</th><th>Nội dung mới</th><th>Cách sửa</th></tr></thead><tbody><tr><td><strong>Org 3 tầng</strong></td><td>Cũ <code>User → Workspace</code> (1 tầng). Mới <code>User → Agency → Workspace</code></td><td>Thêm 1 đoạn + sơ đồ org vào §1.1. Nguồn <code>ba/01-organization-structure.md</code></td></tr><tr><td><strong>Role theo Workspace</strong></td><td>Cũ RBAC 6 role cố định. Mới role gán theo Workspace (<code>OWNER/MANAGER/MEMBER</code>)</td><td>Sửa §4 Responsibility + mọi chỗ nhắc RBAC. Nguồn <code>ba/10-roles-permissions-matrix.md</code></td></tr><tr><td><strong>Hợp đồng 3 tầng</strong></td><td>Media Package (mẫu) → Media Campaign (kế hoạch) → Task backlog</td><td>Thêm vào scope. Nguồn <code>ba/04-media-package-campaign.md</code></td></tr><tr><td><strong>Task 3 loại</strong></td><td>Post / Livestream / Survey-Form, chung 1 Approval Sequence</td><td>Nguồn <code>ba/05-content-task-workflow.md</code></td></tr><tr><td><strong>Client ngoài Agency</strong></td><td>Client = actor ngoài, profile tái sử dụng xuyên Agency</td><td>Nguồn <code>ba/02-authentication-profile.md</code></td></tr><tr><td><strong>ThirdPartyCollaborator</strong></td><td>Đối tác báo/banner/TV, theo dõi thủ công</td><td>Nguồn <code>ba/07-publishing-social-collaborator.md</code></td></tr></tbody></table><hr><h2 id="_3-risks-§1-3-—-chinh-so-lieu-le-bo-sung" tabindex="-1">3. Risks (§1.3) — chỉnh số liệu lẻ + bổ sung <a class="header-anchor" href="#_3-risks-§1-3-—-chinh-so-lieu-le-bo-sung" aria-label="Permalink to &quot;3. Risks (§1.3) — chỉnh số liệu lẻ + bổ sung&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Hiện tại</th><th>Sửa thành</th><th>Cách sửa</th></tr></thead><tbody><tr><td>Risk #3</td><td>OAuth token for <strong>5 platforms</strong></td><td><strong>4 platforms</strong> (Facebook, Instagram, TikTok, Threads)</td><td>Sửa số, thêm tên platform</td></tr><tr><td>Risk #1</td><td>AI API: Groq, Stability AI, Google Veo</td><td>Cập nhật theo feature AI thực tế (caption, ambassador, image/video gen) — BA 06 không còn pin provider cũ</td><td>Bỏ tên provider cụ thể hoặc ghi chung &quot;AI provider (caption/image/video)&quot;</td></tr><tr><td>Risk #5</td><td>Multi-tenancy leakage (workspace isolation)</td><td>Nâng thành <strong>Agency/Workspace 3-tầng isolation</strong></td><td>Cập nhật mô tả</td></tr></tbody></table><p><strong>Thêm risk mới</strong> (từ BA V2):</p><ul><li>PayOS payment failure (thanh toán thất bại, webhook)</li><li>Subscription/Billing edge case (hủy, downgrade, credit AI)</li><li>Đàm phán / Approval Sequence phức tạp — <strong>task rủi ro cao nhất</strong> theo <code>sprint-plan-v2-overview.md</code></li></ul><hr><h2 id="_4-training-§2-3-tech-stack" tabindex="-1">4. Training (§2.3) + Tech stack <a class="header-anchor" href="#_4-training-§2-3-tech-stack" aria-label="Permalink to &quot;4. Training (§2.3) + Tech stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Hiện tại</th><th>Sửa thành</th><th>Cách sửa</th></tr></thead><tbody><tr><td>React version</td><td>React 18</td><td><strong>React 19</strong> (web-dashboard đang dùng React 19)</td><td>Sửa ở §2.3 + bảng tech stack (nếu trích lại)</td></tr><tr><td>AI</td><td>Groq/Stability/Veo</td><td>Bỏ provider cũ</td><td>Đồng bộ với §1.3</td></tr><tr><td>Thiếu training</td><td>—</td><td>Thêm: PayOS, subscription/billing, OAuth 4 platform, mô hình 3 tầng</td><td>Thêm hàng vào bảng Training</td></tr></tbody></table><hr><h2 id="_5-responsibility-§4-—-thieu-nguoi" tabindex="-1">5. Responsibility (§4) — thiếu người <a class="header-anchor" href="#_5-responsibility-§4-—-thieu-nguoi" aria-label="Permalink to &quot;5. Responsibility (§4) — thiếu người&quot;">​</a></h2><ul><li>D/R/S/I matrix &quot;5 members&quot; nhưng chỉ ghi 4 assignee: <strong>Trung, Phước, Tuấn, Ân</strong>.</li><li><strong>Thiếu Lộc</strong> (AI Sub-lead).</li><li>Cách sửa: thêm Lộc, lấy phân công chi tiết từ <code>sprint-plan-v2-overview.md</code> (mục &quot;Ai làm gì, từng sprint&quot;).</li></ul><hr><h2 id="_6-linh-tinh" tabindex="-1">6. Linh tinh <a class="header-anchor" href="#_6-linh-tinh" aria-label="Permalink to &quot;6. Linh tinh&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Cách sửa</th></tr></thead><tbody><tr><td>Date tiêu đề &quot;August 2026&quot;</td><td>Cập nhật Sept 2026 (BA V2 ngày 2026-09-14)</td></tr><tr><td>Table 1 Record of Changes trống</td><td>Điền sau khi áp dụng toàn bộ thay đổi trên</td></tr></tbody></table><hr><h2 id="thu-tu-thuc-hien" tabindex="-1">Thứ tự thực hiện <a class="header-anchor" href="#thu-tu-thuc-hien" aria-label="Permalink to &quot;Thứ tự thực hiện&quot;">​</a></h2><ol><li>Chốt số FR chuẩn (đếm lại CSV vs <code>feature/</code>).</li><li>Dựng lại WBS theo 9 domain + 109 FR (S/M/C + man-day).</li><li>Viết lại phần mô hình org/RBAC (3 tầng, role theo Workspace).</li><li>Sửa risk, training, responsibility, date.</li><li>Điền Record of Changes.</li></ol>',33)])])}const u=e(a,[["render",r]]);export{p as __pageData,u as default};
